const fixtures = [
  {id:'F01_FLUID_LEAK_USABLE_PHOTO', message:'Mi camioneta está botando aceite desde ayer.', media:[{type:'photo'}], expected:{requestType:'diagnostic_request',route:'appointment'}},
  {id:'F02_FLUID_LEAK_UNUSABLE_PHOTO', message:'Hay una fuga debajo del carro.', media:[{type:'photo',quality:'dark_blurry'}], expected:{requestType:'diagnostic_request',route:'request_evidence'}},
  {id:'F03_SCHEDULED_MAINTENANCE_NO_MEDIA', message:'Quiero mantenimiento de 80 mil km para mi Corolla.', media:[], expected:{requestType:'scheduled_maintenance',route:'appointment'}},
  {id:'F04_WARRANTY_COMEBACK', message:'Sigue sonando lo mismo que repararon la semana pasada.', history:{priorWorkOrderId:'wo-previous'}, media:[], expected:{requestType:'warranty_or_comeback',route:'human_review'}},
  {id:'F05_ROADSIDE_ASSISTANCE', message:'No prende y estoy varado. ¿Pueden mandar grúa?', vehicleOperationalState:'immobilized_reported', media:[], expected:{requestType:'roadside_assistance',route:'roadside_human_escalation'}}
];
const has=(t,terms)=>terms.some(x=>String(t||'').toLowerCase().includes(x));
const results=[];
for(const f of fixtures){
  const roadside=String(f.vehicleOperationalState||'').startsWith('immobilized')||has(f.message,['varado','grúa','grua']);
  const comeback=!!f.history?.priorWorkOrderId&&has(f.message,['repararon','sigue','garantía','garantia']);
  const maintenance=has(f.message,['mantenimiento','80 mil','80,000','80000']);
  const unusable=(f.media||[]).some(m=>m.quality==='dark_blurry');
  let requestType='diagnostic_request', route='appointment', humanReviewRequired=false;
  if(roadside){requestType='roadside_assistance';route='roadside_human_escalation';humanReviewRequired=true;}
  else if(comeback){requestType='warranty_or_comeback';route='human_review';humanReviewRequired=true;}
  else if(maintenance){requestType='scheduled_maintenance';route='appointment';}
  else if(unusable){route='request_evidence';}
  const mechanicalDiagnosisProduced=false;
  if(requestType!==f.expected.requestType) throw new Error(`${f.id}: requestType expected=${f.expected.requestType} actual=${requestType}`);
  if(route!==f.expected.route) throw new Error(`${f.id}: route expected=${f.expected.route} actual=${route}`);
  if(mechanicalDiagnosisProduced!==false) throw new Error(`${f.id}: diagnosis boundary violated`);
  if((route==='human_review'||route==='roadside_human_escalation')&&!humanReviewRequired) throw new Error(`${f.id}: missing human review`);
  results.push({id:f.id,requestType,route,humanReviewRequired,mechanicalDiagnosisProduced});
}
if(results.length!==5) throw new Error(`CASE002_FIXTURE_COUNT expected=5 actual=${results.length}`);
return [{json:{case:'CASE-002',probe:'PASS',fixturesPassed:results.length,externalProvidersInvoked:false,results}}];
